function renderGrid(){if(!kind||!$('#grid'))return;if(kind==='record')renderTabs();const fav=favorites();let data=all(kind).filter(x=>match(x)&&(onlyFav?fav.has(kind+'_'+x.id):tab==='全部'||x.category===tab)&&(!(kind==='resource'&&tab==='免费字体'&&!onlyFav&&fontTab!=='全部')||x.label===fontTab));$('#count').textContent=`${data.length} 项${onlyFav?'收藏':''}`;$('#fav-filter').classList.toggle('primary',onlyFav);$('#admin-tools').innerHTML=admin?`<button class="btn" data-action="refresh">${icon('refresh')} 刷新</button><button class="btn primary" data-action="new" ${cloud?'':'disabled'}>${icon('plus')} 新增${kind==='record'?'记录':kind==='resource'?'资源':'色卡'}</button>`:`<button class="btn" data-action="account">${icon('lock')} 管理员登录</button>`;$('#notice').textContent=kind==='record'?'作品档案 · 项目版本 · 灵感笔记。自建记录默认私密，只有主动公开的记录可供访客查看。':kind==='palette'?'精选原创配色；传统色及年度色为屏幕近似色值，印刷需以正式色卡为准。': '资源链接指向来源网站，下载和使用前核对授权；不随网站打包字体文件。';const grid=$('#grid');grid.className=kind+'-grid';grid.style.setProperty('--sample-size',sampleSize+'px');if(!data.length){grid.innerHTML='<div class="empty">没有符合条件的内容。试试其他关键词或分类。</div>';return}if(kind==='record'){data.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));const years=[...new Set(data.map(x=>(x.date||'未归档').slice(0,4)))];grid.innerHTML=years.map(y=>`<div class="yearline"><b>${esc(y)}</b><span class="mini">${data.filter(x=>(x.date||'未归档').slice(0,4)===y).length} 项记录</span></div><div class="grid record-grid">${data.filter(x=>(x.date||'未归档').slice(0,4)===y).map(x=>tile(x,fav)).join('')}</div>`).join('')}else grid.innerHTML=`<div class="grid">${data.map(x=>tile(x,fav)).join('')}</div>`}
function tile(x,fav){const id=esc(x.id),isFav=fav.has(kind+'_'+x.id),favorite=btn('star','favorite',isFav?'取消收藏':'收藏',`data-id="${id}" style="${isFav?'color:#b38a36;background:var(--soft)':''}"`),manage=admin?btn('edit','edit','编辑',`data-id="${id}"`)+btn('trash','delete','删除',`data-id="${id}"`):'';let visual,sub,action;if(kind==='palette'){const cs=(x.colors||[]).filter(hex);if(!cs.length)cs.push('#888888');const grad=x.category==='渐变色彩'&&cs.length>1;visual=`<div class="swatch" style="${grad?'background:linear-gradient('+Number(x.angle||0)+'deg,'+cs.map((c,i)=>c+(x.stops?.length===cs.length?' '+x.stops[i]+'%':'')).join(',')+')':''}">${grad?`<button data-copy="${esc('linear-gradient('+Number(x.angle||0)+'deg, '+cs.map((c,i)=>c+(x.stops?.length===cs.length?' '+x.stops[i]+'%':'')).join(', ')+')')}"><span>复制渐变 CSS</span></button>`:cs.map(c=>`<button style="background:${c}" data-copy="${c}" aria-label="复制 ${c}"><span>${c}</span></button>`).join('')}</div>`;sub=`<div class="hexes">${cs.map(c=>`<button data-copy="${c}">${c}</button>`).join('')}</div>`;action=btn('palette','use-palette','在实验室编辑',`data-id="${id}"`)}else if(kind==='resource'){const font=loadedFonts.get(x.id)||x.font||'',family=font.replace(/["'\\;{}<>]/g,''),fallback=x.label==='宋体'?'serif':x.label==='楷体'||x.label==='书法'||x.label==='手写'?'KaiTi, STKaiti, serif':'sans-serif';visual=cover(x.cover)?`<div class="cover"><img src="${cover(x.cover)}" loading="lazy" alt="${esc(x.title)}"></div>`:`<div class="resource-preview">${x.category==='免费字体'?`<div class="sample" style="font-family:'${esc(family)}',${fallback}">${esc(sample||'Aa 字体预览')}</div><span class="sample-sub">Aa / 0123456789</span>`:icon(x.category==='规范文档'?'file':x.category==='其他资源'?'folder':'image')+'<span class="sample-sub">RESOURCE / '+esc(x.category)+'</span>'}</div>`;sub=`<div class="tile-sub">${esc(x.label||x.category)} · ${esc(x.license||'核对来源授权')}</div>`;action=(x.category==='免费字体'?btn('type','load-font','加载本地字体',`data-id="${id}"`):'')+(url(x.url)?`<a class="iconbtn" href="${esc(url(x.url))}" target="_blank" rel="noopener noreferrer" title="打开官方来源" aria-label="打开官方来源">${icon('external')}</a>`:'')}else{const backgrounds=['linear-gradient(125deg,#24293c,#58679c)','linear-gradient(125deg,#525774,#9390b1)','linear-gradient(125deg,#35564d,#86ab98)'];visual=`<button class="cover" style="width:100%;border:0;background:${backgrounds[(x.visual||0)%backgrounds.length]}" data-action="detail" data-id="${id}">${cover(x.cover)?`<img src="${cover(x.cover)}" loading="lazy" alt="${esc(x.title)}">`:`<span class="cover-text">${esc(x.label||x.title)}</span><small>${esc(x.category||'ARCHIVE')}</small>`}</button>`;sub=`<div class="tile-sub">${esc(x.date||'')} · ${esc(x.category||'')}${x.projectVersion?' · '+esc(x.projectVersion):''}</div>${x.tags?.length?`<div class="record-tags">${x.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:''}${admin&&x.version?`<div class="record-meta">${icon(x.public?'external':'lock')} ${x.public?'公开':'私密'}${x.gallery?.length?' · '+(x.gallery.length+(cover(x.cover)?1:0))+' 张图':''}</div>`:''}`;action=btn('external','detail','查看详情',`data-id="${id}"`)}return `<article class="tile">${visual}<div class="tile-body"><div class="tile-title">${esc(x.title)}</div>${sub}<div class="tile-actions"><span class="mini">${kind==='palette'?'COLOR SPACE':kind==='resource'?'SOURCE / 授权详情':'DESIGN ARCHIVE'}</span><div class="right">${favorite}${action}${manage}</div></div></div></article>`}
function dialog(title,body,type='standard'){const d=$('#dialog');d.dataset.variant=type;d.setAttribute('aria-label',title);d.innerHTML=`<div class="dialog-inner"><div class="dialog-head"><div><span class="dialog-kicker">PRIVATE NAV / STUDIO</span><h2>${esc(title)}</h2></div>${btn('close','close','关闭')}</div>${body}</div>`;if(!d.open)d.showModal()}
function closeDialog(){if($('#dialog').open)$('#dialog').close()}
function account(){if(admin){const modules=[['nav','导航管理','网站与分类','/cn/'],['time','记录管理','作品、项目与灵感','/time/'],['palette','色彩管理','色卡与渐变','/colors/gradient/'],['folder','资源管理','字体与设计素材','/resource/fonts/']];dialog('管理中心',`<div class="admin-profile"><div class="admin-avatar">${icon('user')}</div><div class="admin-name"><small>ADMINISTRATOR</small><strong>${esc(authName||'管理员')}</strong><span>统一账号 · 创意工作台</span></div><span class="admin-cloud ${cloud?'online':''}"><i></i>${cloud?'云端已连接':'云端离线'}</span></div><div class="modal-section-label">WORKSPACE / 工作台管理</div><div class="admin-grid">${modules.map(([i,n,d,h])=>`<a class="admin-module" href="${h}"><span class="module-icon">${icon(i)}</span><strong>${n}</strong><small>${d}</small><span class="module-arrow">${icon('external')}</span></a>`).join('')}</div><button class="admin-backup" data-action="backup-studio" ${cloud?'':'disabled'}>${icon('download')}<span><b>导出工作台数据</b><small>记录、色彩、资源与收藏 · JSON</small></span>${icon('arrow')}</button><div class="admin-footer"><span>与私人导航共用登录会话</span><button class="logout-link" data-action="logout">${icon('lock')} 退出登录</button></div>`,'account');return}dialog('管理员登录',`<div class="login-intro"><div class="admin-avatar">${icon('lock')}</div><div><strong>欢迎回到工作台</strong><span>使用原私人导航管理员账号</span></div></div><form id="login-form" class="dialog-inner" style="padding:0"><label>用户名<input type="text" name="username" autocomplete="username" required></label><label>密码<input type="password" name="password" autocomplete="current-password" required></label><button class="btn primary" type="submit">登录工作台 ${icon('arrow')}</button><span class="notice" id="login-error" role="status"></span></form>`,'login');$('#login-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=$('button[type=submit]',f);b.disabled=true;try{await request('/api/state?mode=login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))});globalNav=null;closeDialog();await refresh({force:true});notify(admin?'登录成功':'登录状态尚未确认')}catch(e){const err=$('#login-error',f);if(err)err.textContent=e.message}finally{b.disabled=false}}}
function detail(id){const x=current(kind,id);if(!x)return;const photos=[x.cover,...(x.gallery||[])].map(cover).filter(Boolean);dialog(x.title,`<div class="record-detail-meta"><span>${esc(x.category)} · ${esc(x.date||'')}</span>${x.projectVersion?`<span>${esc(x.projectVersion)}</span>`:''}${admin?`<span>${x.public?'公开':'私密'}</span>`:''}</div>${photos.length?`<div class="record-gallery"><button class="gallery-main" id="gallery-zoom" aria-label="放大图片"><img id="gallery-image" src="${photos[0]}" alt="${esc(x.title)} · 1"></button>${photos.length>1?`<div class="gallery-thumbs">${photos.map((p,i)=>`<button type="button" data-photo="${i}" aria-label="第 ${i+1} 张" aria-pressed="${i===0}"><img src="${p}" alt=""></button>`).join('')}</div>`:''}<span class="mini" id="gallery-count">1 / ${photos.length} · 点击图片放大</span></div>`:''}${x.tags?.length?`<div class="record-tags">${x.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:''}<p>${esc(x.description||'暂无详情')}</p>${url(x.url)?`<a class="btn primary" href="${esc(url(x.url))}" target="_blank" rel="noopener noreferrer">打开链接 ${icon('external')}</a>`:''}`,'detail');if(photos.length){let index=0;const img=$('#gallery-image'),zoom=$('#gallery-zoom');$$('[data-photo]',$('#dialog')).forEach(b=>b.onclick=()=>{index=+b.dataset.photo;img.src=photos[index];img.alt=x.title+' · '+(index+1);zoom.classList.remove('zoomed');$('#gallery-count').textContent=(index+1)+' / '+photos.length+' · 点击图片放大';$$('[data-photo]',$('#dialog')).forEach(t=>t.setAttribute('aria-pressed',String(t===b)))});zoom.onclick=()=>zoom.classList.toggle('zoomed')}}
async function compress(file,limit=360000,maxSide=1000){if(!file||!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>15*1024*1024)throw new Error('请选择 15MB 内 PNG/JPEG/WebP');const bitmap=await createImageBitmap(file);const c=document.createElement('canvas'),scale=Math.min(1,maxSide/Math.max(bitmap.width,bitmap.height));c.width=Math.max(1,Math.round(bitmap.width*scale));c.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=c.getContext('2d');ctx.fillStyle='#f4f4f5';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(bitmap,0,0,c.width,c.height);bitmap.close();let q=.88,s=c.toDataURL('image/jpeg',q);while(s.length>limit&&q>.25){q-=.1;s=c.toDataURL('image/jpeg',q)}if(s.length>limit)throw new Error('图片压缩后仍过大');return s}
function edit(id,initial){if(!admin||!cloud){account();return}const x=id?current(kind,id):initial||{},orig=kind,version=x?.version||0,category=x?.category||(tab==='全部'?'项目记录':tab);let image=x?.cover||'',gallery=[...(x?.gallery||[])];const categoryOptions=cats[kind].filter(c=>c!=='全部');dialog(id?(orig==='record'?'编辑记录':'编辑条目'):(orig==='record'?'新增记录':'新增条目'),`<form id="edit-form" class="dialog-inner" style="padding:0"><label>名称<input type="text" name="title" maxlength="120" required value="${esc(x?.title||'')}"></label><label>分类${kind==='record'?`<input name="category" type="text" maxlength="40" list="record-categories" value="${esc(category)}" required><datalist id="record-categories">${recordCategories().filter(c=>c!=='全部').map(c=>`<option value="${esc(c)}"></option>`).join('')}</datalist>`:`<select name="category">${categoryOptions.map(c=>`<option ${c===category?'selected':''}>${esc(c)}</option>`).join('')}</select>`}</label>${kind==='palette'?`<label>颜色（2–8 个，或单色；逗号分隔）<input type="text" name="colors" required value="${esc((x?.colors||labColors).join(', '))}"></label><label>角度<input type="number" name="angle" min="0" max="360" value="${Number(x?.angle??angle)}"></label>`:`${kind==='record'?`<div class="form-pair"><label>日期<input type="date" name="date" value="${esc(x?.date||new Date().toISOString().slice(0,10))}"></label><label>项目版本<input type="text" name="projectVersion" maxlength="40" placeholder="例如 V1.0" value="${esc(x?.projectVersion||'')}"></label></div><label>标签（逗号分隔）<input type="text" name="tags" maxlength="300" placeholder="电商主图, 品牌设计" value="${esc((x?.tags||[]).join(', '))}"></label><label class="privacy-choice">可见范围<select name="visibility"><option value="private" ${x?.public?'':'selected'}>私密 · 仅管理员</option><option value="public" ${x?.public?'selected':''}>公开 · 访客可查看</option></select></label>`:`<label>字体分类 / 标签<input type="text" name="label" value="${esc(x?.label||'')}"></label><label>本机字体名称<input type="text" name="font" value="${esc(x?.font||'')}"></label><label>授权说明<input type="text" name="license" value="${esc(x?.license||'')}"></label>`}<label>链接<input type="text" name="url" value="${esc(x?.url||'')}"></label><label>封面上传<input type="file" id="cover-file" accept="image/png,image/jpeg,image/webp"></label><div class="row"><img id="cover-preview" ${cover(image)?`src="${cover(image)}"`:'hidden'} alt="封面预览"><button class="btn" type="button" id="clear-cover">移除封面</button></div>${kind==='record'?`<label>作品图片（另可添加 3 张）<input type="file" id="gallery-files" accept="image/png,image/jpeg,image/webp" multiple></label><div id="edit-gallery" class="edit-gallery"></div><span class="notice">云端保存压缩预览图，不保存原始高清文件。需要原图可在链接栏附上原图地址。</span>`:''}`}<label>说明<textarea name="description" maxlength="5000">${esc(x?.description||'')}</textarea></label><button class="btn primary" type="submit">保存到云端</button><span class="notice" id="edit-error"></span></form>`);const form=$('#edit-form'),file=$('#cover-file'),galleryInput=$('#gallery-files');if(galleryInput){const draw=()=>{const g=$('#edit-gallery',form);g.innerHTML=gallery.map((p,i)=>`<div><img src="${cover(p)}" alt="作品 ${i+1}"><button type="button" data-remove-photo="${i}" aria-label="移除图片 ${i+1}">${icon('close')}</button></div>`).join('');$$('[data-remove-photo]',g).forEach(b=>b.onclick=()=>{if(editBusy)return;gallery.splice(+b.dataset.removePhoto,1);draw()})};draw();galleryInput.onchange=async()=>{if(editBusy)return;const selected=[...galleryInput.files];if(selected.length+gallery.length>3){notify('最多添加 3 张作品图片');galleryInput.value='';return}editBusy=true;try{const next=[];for(const f of selected)next.push(await compress(f,85000,1000));gallery.push(...next);draw()}catch(e){notify(e.message)}finally{editBusy=false;galleryInput.value=''}}}if(file){file.onchange=async()=>{if(!file.files[0])return;editBusy=true;try{image=await compress(file.files[0],orig==='record'?110000:360000);const preview=$('#cover-preview',form);preview.src=image;preview.hidden=false}catch(e){notify(e.message)}finally{editBusy=false}};$('#clear-cover').onclick=()=>{image='';$('#cover-preview').hidden=true;file.value=''}}$('#edit-form').onsubmit=async e=>{e.preventDefault();if(editBusy)return;const form=e.currentTarget,b=$('button[type=submit]',form);b.disabled=true;try{const d=Object.fromEntries(new FormData(form));if(d.url){const link=url(d.url);if(!link)throw new Error("请输入有效 HTTP/HTTPS 链接");d.url=link;}if(orig==='palette'){d.colors=d.colors.split(/[,，\s]+/).filter(Boolean).map(s=>s.toUpperCase());if(d.colors.length<1||d.colors.length>8||d.colors.some(s=>!hex(s)))throw new Error('请输入 1–8 个有效 HEX 色值');d.angle=Number(d.angle);if(x?.stops?.length===d.colors.length)d.stops=x.stops}else {d.cover=image;if(orig==='record'){d.gallery=gallery;d.public=d.visibility==='public';delete d.visibility;d.tags=d.tags.split(/[,，]+/).map(t=>t.trim()).filter(Boolean).slice(0,12);if(d.category.trim()==='全部')throw new Error('请选择具体分类');if(JSON.stringify(d).length>420000)throw new Error('图片总大小超限，请移除部分图片或重新上传封面')}}await mutate(orig,id||('custom_'+(crypto.randomUUID?.()||Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join(''))),d,'save',version);if(orig==='record'){tab=d.category.trim();query='';onlyFav=false;$('#page-search').value=''}closeDialog();notify('已保存到云端');renderGrid()}catch(e){const err=$('#edit-error',form);if(err)err.textContent=e.message}finally{b.disabled=false}}}
async function loadFont(id){const input=document.createElement('input');input.type='file';input.accept='.ttf,.otf,.woff,.woff2';input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>30*1024*1024){notify('字体文件超过30MB');return}try{const name='StudioLocal_'+id.replace(/[^a-zA-Z0-9_]/g,'_'),font=new FontFace(name,await file.arrayBuffer());await font.load();document.fonts.add(font);loadedFonts.set(id,name);renderGrid();notify('字体已加载，仅在当前页面预览')}catch{notify('字体文件无法加载')}};input.click()}
function gradientCSS(){return `linear-gradient(${angle}deg, ${labColors.map((c,i)=>c+' '+labStops[i]+'%').join(', ')})`}
function normalizeStops(){labStops=labColors.map((_,i)=>Math.round(i/(labColors.length-1||1)*100))}
function renderLab(){const lab=$('#lab');if(!lab)return;lab.hidden=false;lab.innerHTML=`<section class="lab"><h2>渐变实验室 <span class="mini">GRADIENT STUDIO</span></h2><div class="lab-grid"><div><div class="lab-preview" id="lab-preview" style="background:${gradientCSS()}">COLOR / STUDIO</div><div class="hexes" style="margin-top:9px" id="lab-convert"></div><div id="extracted" class="hexes" style="margin-top:8px"></div></div><div class="lab-fields">${labColors.map((c,i)=>`<label>色标 ${i+1}<input type="color" data-lab-color="${i}" value="${c}"><input type="text" data-lab-hex="${i}" value="${c}" style="width:105px" aria-label="颜色 ${i+1}"><input type="range" min="0" max="100" value="${labStops[i]}" data-lab-stop="${i}" aria-label="色标位置 ${i+1}"><span data-stop-label="${i}">${labStops[i]}%</span>${labColors.length>2?`<button class="btn" data-remove-stop="${i}">移除</button>`:''}</label>`).join('')}<label>角度<input type="range" id="lab-angle" min="0" max="360" value="${angle}"><span id="lab-angle-value">${angle}°</span></label><div class="pills"><button class="btn" data-action="lab-add" ${labColors.length>=8?'disabled':''}>＋ 色标</button><button class="btn" data-action="lab-random">随机</button><button class="btn" data-action="lab-reverse">反转</button><button class="btn" data-action="image-colors">图片取色</button></div><code id="lab-css">${esc(gradientCSS())}</code><div class="pills"><button class="btn primary" data-action="lab-copy">复制 CSS</button><button class="btn" data-action="lab-png">PNG</button><button class="btn" data-action="lab-svg">SVG</button><button class="btn" data-action="lab-ase">ASE</button><button class="btn" data-action="lab-save">云端保存</button></div></div></div></section>`;$$('[data-lab-color]',lab).forEach(e=>e.oninput=()=>{const i=+e.dataset.labColor;labColors[i]=e.value.toUpperCase();$(`[data-lab-hex="${i}"]`).value=labColors[i];updateLab()});$$('[data-lab-hex]',lab).forEach(e=>e.onchange=()=>{const i=+e.dataset.labHex;if(!hex(e.value)){e.value=labColors[i];notify('HEX 格式无效');return}labColors[i]=e.value.toUpperCase();$(`[data-lab-color="${i}"]`).value=labColors[i];updateLab()});$$('[data-lab-stop]',lab).forEach(e=>e.oninput=()=>{const i=+e.dataset.labStop;labStops[i]=Math.max(i?labStops[i-1]:0,Math.min(i<labStops.length-1?labStops[i+1]:100,+e.value));e.value=labStops[i];$(`[data-stop-label="${i}"]`).textContent=labStops[i]+'%';updateLab()});$('#lab-angle').oninput=e=>{angle=+e.target.value;updateLab()};updateLab()}
function channels(c){return [1,3,5].map(i=>parseInt(c.slice(i,i+2),16))}
function conversion(c){const [r,g,b]=channels(c),[R,G,B]=[r,g,b].map(x=>x/255),max=Math.max(R,G,B),min=Math.min(R,G,B),d=max-min,l=(max+min)/2,s=d?d/(1-Math.abs(2*l-1)):0,h=d?((max===R?(G-B)/d:max===G?(B-R)/d+2:(R-G)/d+4)*60+360)%360:0,k=1-max,cm=[R,G,B].map(x=>k===1?0:(1-x-k)/(1-k));return [`RGB ${r}, ${g}, ${b}`,`HSL ${Math.round(h)}°, ${Math.round(s*100)}%, ${Math.round(l*100)}%`,`CMYK ${[...cm,k].map(x=>Math.round(x*100)).join(', ')}%`]}
