header();if(page==='home')home();else{const params=new URLSearchParams(location.search);query=params.get('q')||'';if(page==='colors'&&params.get('lab')==='1')labOpen=true;if(params.get('all')==='1'&&kind!=='record'){const item=all(kind).find(x=>x.title===query);if(item){tab=item.category;if(kind==='palette')history.replaceState(null,'','/colors/'+colorPaths[cats.palette.indexOf(tab)]+'/?'+params);else history.replaceState(null,'','/resource/'+resourcePaths[cats.resource.indexOf(tab)]+'/?'+params)}}pageShell()}document.addEventListener('click',handleClick);$('#dialog').addEventListener('close',()=>{if(kind)renderGrid()});addEventListener('focus',()=>{if(!$('#dialog').open)refresh({quiet:true})});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!$('#dialog').open)refresh({quiet:true})});addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#dialog').open||$('#dialog').dataset.variant==='search')globalSearch()}});refresh({quiet:true});setInterval(()=>{if(admin&&!document.hidden&&!$('#dialog').open)refresh({quiet:true})},45000);if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('/sw.js',{scope:'/',updateViaCache:'none'}).catch(()=>{});
